USE email_verifier;
CREATE TABLE IF NOT EXISTS worker_nodes (worker_id varchar(128) NOT NULL PRIMARY KEY,hostname varchar(255) NOT NULL,status varchar(24) NOT NULL DEFAULT 'online',current_job_id varchar(36) NULL,processed_total bigint unsigned NOT NULL DEFAULT 0,last_seen datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),started_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX worker_nodes_seen_idx(last_seen)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS monitored_domains (id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,domain varchar(255) NOT NULL UNIQUE,enabled tinyint(1) NOT NULL DEFAULT 1,interval_minutes int unsigned NOT NULL DEFAULT 60,next_check_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),last_check_at datetime(3) NULL,last_change_at datetime(3) NULL,last_hash char(64) NULL,created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX monitored_domains_due_idx(enabled,next_check_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS domain_monitor_snapshots (id bigint unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,domain_id bigint unsigned NOT NULL,domain varchar(255) NOT NULL,changed tinyint(1) NOT NULL DEFAULT 0,change_summary text NULL,snapshot json NOT NULL,created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX domain_snapshots_domain_idx(domain_id,id),CONSTRAINT domain_snapshots_fk FOREIGN KEY(domain_id) REFERENCES monitored_domains(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
